int register_mii_bus(struct mii_bus *bus, struct module *owner) {
    int ret;
    struct phy_device *phy;
    int i;

    if (!bus || !bus->read || !bus->write) {
        return -EINVAL;
    }

    mutex_init(&bus->mutex);

    ret = device_register(&bus->dev);
    if (ret < 0) {
        return ret;
    }

    bus->dev.driver = NULL;
    bus->dev.release = mii_bus_release;
    bus->owner = owner;

    for (i = 0; i < PHY_MAX_ADDR; i++) {
        phy = phy_device_create(bus, i);
        if (!phy) {
            while (--i >= 0) {
                phy_device_remove(phy);
            }
            device_unregister(&bus->dev);
            return -ENOMEM;
        }

        ret = phy_device_register(phy);
        if (ret < 0) {
            phy_device_remove(phy);
            while (--i >= 0) {
                phy_device_unregister(bus, i);
                phy_device_remove(bus->phy[i]);
            }
            device_unregister(&bus->dev);
            return ret;
        }
    }

    dev_info(&bus->dev, "Probed MII bus %s with %d PHY devices\n",
             bus->id, PHY_MAX_ADDR);

    bus->state = MII_BUS_READY;

    return 0;
}

int mii_bus_register(struct mii_bus *bus, struct module *owner)
{
    int ret;
    int i;
    struct phy_device *phy_dev;

    if (!bus || !bus->name || !bus->read || !bus->write)
        return -EINVAL;

    ret = device_register(&bus->dev);
    if (ret) {
        return ret;
    }

    mutex_init(&bus->bus_mutex);

    if (bus->reset) {
        ret = bus->reset(bus);
        if (ret < 0) {
            device_unregister(&bus->dev);
            return ret;
        }
    }

    for (i = 0; i < PHY_MAX_ADDR; i++) {
        phy_dev = get_phy_device(bus, i, false);
        if (IS_ERR(phy_dev)) {
            ret = PTR_ERR(phy_dev);
            while (--i >= 0) {
                phy_device_remove(i);
                phy_device_free(i);
            }
            device_unregister(&bus->dev);
            return ret;
        }

        if (phy_dev) {
            ret = phy_device_register(phy_dev);
            if (ret) {
                while (--i >= 0) {
                    phy_device_remove(i);
                    phy_device_free(i);
                }
                device_unregister(&bus->dev);
                return ret;
            }
        }
    }

    bus->state = mii_bus_polling;
    dev_info(&bus->dev, "Probed MII bus: %s\n", bus->name);

    return 0;
}

int register_mii_bus(struct mii_bus *bus, struct module *owner)
{
    int ret;
    int i;

    if (!bus || !bus->name || !bus->phy_mask || !bus->read || !bus->write)
        return -EINVAL;

    mutex_init(&bus->bus_mutex);

    ret = device_register(&bus->dev);
    if (ret) {
        return ret;
    }

    bus->dev.class = &mii_bus_class;
    dev_set_drvdata(&bus->dev, bus);
    dev_set_owner(&bus->dev, owner);

    for (i = 0; i < PHY_MAX_ADDR; i++) {
        if (bus->phy_mask & (1 << i))
            continue;

        ret = phy_scan(bus, i);
        if (ret < 0)
            goto out_unregister;
    }

    netdev_info(bus->dev.parent, "Probing MII bus %s\n", bus->name);
    bus->state = MII_BUS_READY;

    return 0;

out_unregister:
    while (--i >= 0) {
        if (bus->phy[i]) {
            phy_disconnect(bus->phy[i]);
            phy_free(bus->phy[i]);
        }
    }
    device_unregister(&bus->dev);
    return ret;
}

int register_mii_bus(struct mii_bus *bus, struct module *owner)
{
    int ret = 0;
    struct phy_device *phy;
    int i;

    if (!bus || !bus->read || !bus->write || !bus->name) {
        return -EINVAL;
    }

    mutex_init(&bus->bus_mutex);

    /* Register the MII bus as a device */
    ret = device_register(&bus->dev);
    if (ret < 0) {
        pr_err("Failed to register MII bus device\n");
        return ret;
    }

    bus->dev.class = &mii_bus_class;
    dev_set_drvdata(&bus->dev, bus);

    /* Handle GPIO reset */
    if (bus->reset_gpio) {
        gpio_set_value(bus->reset_gpio, 0);
        msleep(100);
        gpio_set_value(bus->reset_gpio, 1);
        msleep(100);
    }

    for (i = 0; i < PHY_MAX_ADDR; i++) {
        phy = get_phy_device(bus, i, false);
        if (IS_ERR(phy)) {
            ret = PTR_ERR(phy);
            if (ret != -ENODEV) {
                pr_err("Failed to get PHY device at address %d\n", i);
                goto error_cleanup;
            }
        } else {
            if (!phy->phy_id) {
                ret = phy_device_register(phy);
                if (ret < 0) {
                    pr_err("Failed to register new PHY device at address %d\n", i);
                    put_device(&phy->dev);
                    goto error_cleanup;
                }
            }
        }
    }

    bus->state = MII_BUS_READY;
    pr_info("MII bus '%s' probed successfully\n", bus->name);

    return 0;

error_cleanup:
    for (i = 0; i < PHY_MAX_ADDR; i++) {
        phy = get_phy_device(bus, i, true);
        if (!IS_ERR(phy)) {
            phy_device_unregister(phy);
            put_device(&phy->dev);
        }
    }

    device_unregister(&bus->dev);
    return ret;
}

int register_mii_bus(struct mii_bus *bus, struct module *owner) {
    int ret;
    int i;

    if (!bus || !bus->name || !bus->read || !bus->write) {
        return -EINVAL;
    }

    mutex_init(&bus->bus_mutex);

    ret = device_register(&bus->dev);
    if (ret) {
        return ret;
    }

    if (bus->reset) {
        ret = bus->reset(bus);
        if (ret) {
            device_unregister(&bus->dev);
            return ret;
        }
    }

    for (i = 0; i < PHY_MAX_ADDR; i++) {
        struct phy_device *phydev;

        phydev = phy_probe(bus, i);
        if (!IS_ERR(phydev)) {
            list_add_tail(&phydev->link, &bus->phy_list);
        } else if (PTR_ERR(phydev) != -ENODEV) {
            device_unregister(&bus->dev);
            return PTR_ERR(phydev);
        }
    }

    dev_info(&bus->dev, "Probing for MII devices\n");

    return 0;
}
